#!/usr/bin/env python3
"""
Release Domino — Complete Full-Stack Installer & Launcher (P1 NVIDIA NIM / LLM + P2 Universal Local/Docker Sandbox + P3 Graph/Risk + P4 2D/3D React Flow UI)
Includes:
  - NVIDIA NIM API Support (NVIDIA_API_KEY / nvapi-... in .env or via Top-Bar UI button) with priority over local Ollama
  - Universal Multi-Stack Local Sandbox (Vite, React, Next.js, Express, FastAPI, Flask, Django, Streamlit, CLI, Static HTML)
    with automatic npm install & Windows directory junction / PATH wiring so vite/next/react-scripts always run
  - Outline-Only Node Status Borders (No Red Glow) + Live Blue Glow on Actively Executing Nodes
  - Interactive 2D React Flow + 3D Rotatable Architecture Space Toggle
  - Smart Windows Port Discovery ([WinError 10013] auto-fallback to open port)

Usage:
    python setup_release_domino_p2.py .\release-domino
    cd release-domino
    python start_server.py
"""
import base64
import io
import os
import stat
import subprocess
import sys
import tarfile
from pathlib import Path

ARCHIVE_B64 = ""


def _force_writable(target: Path) -> None:
    if not target.exists():
        return
    for root, dirs, files in os.walk(str(target)):
        for d in dirs:
            dp = os.path.join(root, d)
            try:
                os.chmod(dp, stat.S_IWRITE | stat.S_IREAD | stat.S_IEXEC)
            except OSError:
                pass
        for fn in files:
            fp = os.path.join(root, fn)
            try:
                os.chmod(fp, stat.S_IWRITE | stat.S_IREAD)
            except OSError:
                pass


def main() -> None:
    target = Path(sys.argv[1] if len(sys.argv) > 1 else "release-domino").resolve()
    print(f"[1/3] Extracting Release Domino Full-Stack (NVIDIA NIM + Universal Vite/Node/Python Sandbox + 2D/3D UI) into: {target}")
    target.mkdir(parents=True, exist_ok=True)
    _force_writable(target)

    raw = base64.b64decode(ARCHIVE_B64)
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tar:
        for member in tar.getmembers():
            if member.issym() or member.islnk():
                continue
            dest_path = target / member.name
            # Never overwrite an existing user .env file so NVIDIA_API_KEY is preserved
            if dest_path.name == ".env" and dest_path.exists():
                continue
            if dest_path.exists() and dest_path.is_file():
                try:
                    os.chmod(str(dest_path), stat.S_IWRITE | stat.S_IREAD)
                except OSError:
                    pass
            try:
                if hasattr(tarfile, "data_filter"):
                    tar.extract(member, path=str(target), filter="data")
                else:
                    tar.extract(member, path=str(target), set_attrs=False)
            except (TypeError, ValueError):
                try:
                    tar.extract(member, path=str(target))
                except Exception:
                    pass
            except PermissionError:
                try:
                    os.chmod(str(dest_path), stat.S_IWRITE | stat.S_IREAD)
                    if dest_path.is_file():
                        os.remove(str(dest_path))
                    tar.extract(member, path=str(target))
                except Exception:
                    pass
            except Exception:
                pass

    _force_writable(target)

    print("[2/3] Initializing demo_shop_repo (2 branches + intentional auth.py conflict + 180d defect history)...")
    subprocess.run([sys.executable, "demo/make_demo_repo.py"], cwd=str(target), check=True)

    print("[3/3] Running automated verification suite (P1 + P2 + P3 + P4)...")
    subprocess.run([sys.executable, "backend/tests/run_all_tests.py"], cwd=str(target), check=True)

    print("\n" + "=" * 78)
    print("Release Domino Full-Stack is ready!")
    print(f"  cd {target}")
    print("  python start_server.py")
    print("=" * 78)


if __name__ == "__main__":
    main()
